// Use the ORIGINAL intent key and the same integration lineage. This workflow never sends or starts a flow.
const config = { apiOrigin: 'https://api.insidedm.io', intentKey: 'REPLACE_WITH_ORIGINAL_INTENT_KEY', kind: 'messages.send' };
if (config.intentKey.includes('REPLACE') || !['messages.send', 'events.publish'].includes(config.kind)) throw new Error('Configure the original key and kind: messages.send or events.publish.');
return [{ json: config }];
